69	/// Parse a block quote.
70	///
71	/// Grammar: `MdQuote = prefix: MdQuotePrefix content: MdBlockList`
72	///
73	/// The first-line `>` is emitted as an `MdQuotePrefix` child of `MdQuote`.
74	/// Continuation `>` markers become `MdQuotePrefix` nodes interleaved in
75	/// the block list (between blocks) or inline item list (within paragraphs).
76	pub(crate) fn parse_quote(p: &mut MarkdownParser) -> ParsedSyntax {
77	    if !at_quote(p) {
78	        return Absent;
79	    }
80	
81	    let max_nesting_depth = p.options().max_nesting_depth;
82	    if p.state().block_quote_depth >= max_nesting_depth {
83	        let range = p.cur_range();
84	        p.error(quote_nesting_too_deep(p, range, max_nesting_depth));
85	        p.state_mut().quote_depth_exceeded = true;
86	        // Wrap recovery tokens in MdBogusBlock (a valid AnyMdBlock child)
87	        // so they don't attach as Skipped trivia on normal content nodes.
88	        let bogus_m = p.start();
89	        p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);
90	        try_bump_quote_marker(p);
91	        let has_indented_code = at_quote_indented_code_start(p);
92	        emit_optional_marker_space(p, has_indented_code);
93	        return Present(bogus_m.complete(p, MD_BOGUS_BLOCK));
94	    }
95	
96	    let m = p.start();
97	    p.state_mut().block_quote_depth += 1;
98	
99	    let marker_space = emit_quote_prefix_node(p);
100	    p.set_virtual_line_start();
101	
102	    parse_quote_block_list(p);
103	
104	    p.state_mut().block_quote_depth -= 1;
105	
106	    let completed = m.complete(p, MD_QUOTE);
107	    let range = completed.range(p);
108	    let indent = 1 + if marker_space { 1 } else { 0 };
109	    p.record_quote_indent(range, indent);
110	    Present(completed)
111	}
