150	/// Save virtual line start position if requested, returning the previous value.
151	fn save_virtual_line_start_if_needed(
152	    p: &mut MarkdownParser,
153	    use_virtual_line_start: bool,
154	) -> Option<Option<biome_rowan::TextSize>> {
