174	/// Emit pre-marker indentation (0-3 spaces/tabs) as MD_QUOTE_INDENT nodes.
175	fn emit_quote_pre_marker_indents(p: &mut MarkdownParser) {
176	    // Direct bounded scan (0-3 cols per CommonMark §5.1): simpler than ParseNodeList
177	    // here because we immediately validate `>` and keep this path no-recovery.
178	    let indent_list_m = p.start();
179	    let mut consumed = 0usize;
180	
181	    while p.at(MD_TEXTUAL_LITERAL) {
182	        let text = p.cur_text();
183	        if !is_whitespace_only(text) {
184	            break;
185	        }
186	
187	        let indent = calculate_indent_width(text);
188	        if consumed + indent > MAX_BLOCK_PREFIX_INDENT {
189	            break;
190	        }
191	
192	        consumed += indent;
193	        let indent_m = p.start();
194	        p.bump_remap(MD_QUOTE_PRE_MARKER_INDENT);
195	        indent_m.complete(p, MD_QUOTE_INDENT);
196	    }
197	
198	    indent_list_m.complete(p, MD_QUOTE_INDENT_LIST);
199	}
