201	/// Calculate indent width accounting for tab expansion (CommonMark §2.2).
202	fn calculate_indent_width(text: &str) -> usize {
203	    text.chars()
204	        .map(|c| if c == '\t' { TAB_STOP_SPACES } else { 1 })
205	        .sum()
206	}
