165	// #region parse_thematic_break_parts
166	
167	/// Parse thematic break content into a MdThematicBreakPartList.
168	///
169	/// Handles both paths:
170	/// - Happy path: MD_THEMATIC_BREAK_LITERAL present -> re-lex into parts
171	/// - Fallback path: individual tokens already available (e.g., after list marker)
172	fn parse_thematic_break_parts(p: &mut MarkdownParser) {
173	    let list_m = p.start();
174	
175	    // Emit block prefix indent (0-3 spaces) as MdIndentToken nodes inside the
176	    // parts list. MdIndentToken is a valid AnyMdThematicBreakPart variant.
