1	//! ATX and Setext heading parsing for Markdown (CommonMark §4.2-4.3).
2	//!
3	//! # ATX Headings (§4.2)
4	//!
5	//! An ATX heading consists of 1-6 `#` characters followed by a space and heading
6	//! text. The number of `#` characters determines the heading level.
7	//!
8	//! ```markdown
9	//! # Heading 1
10	//! ## Heading 2
11	//! ### Heading 3
12	//! ```
13	//!
14	//! # Setext Headings (§4.3)
15	//!
16	//! A setext heading consists of one or more lines of text followed by an
17	//! underline of `=` (level 1) or `-` (level 2) characters.
18	//!
19	//! ```markdown
20	//! Heading 1
21	//! =========
22	//!
23	//! Heading 2
24	//! ---------
25	//! ```
26	
27	use crate::parser::MarkdownParser;
28	use crate::syntax::inline::EmphasisContext;
29	use biome_markdown_syntax::{T, kind::MarkdownSyntaxKind::*};
30	use biome_parser::{
31	    Parser,
32	    prelude::ParsedSyntax::{self, *},
33	};
34	
35	use crate::syntax::MAX_BLOCK_PREFIX_INDENT;
36	use crate::syntax::parse_any_inline;
