627	fn inline_has_non_whitespace(p: &MarkdownParser, start: usize, end: usize) -> bool {
628	    if end <= start {
629	        return false;
630	    }
631	
632	    let source = p.source().source_text();
633	    if end > source.len() {
634	        return false;
635	    }
636	
637	    !source[start..end]
638	        .trim_matches(|c: char| matches!(c, ' ' | '\t' | '\r' | '\n'))
