647	/// Token-based check: is the current line a setext underline?
648	///
649	/// Call after consuming a NEWLINE token. Skips 0–3 columns of leading whitespace
650	/// (tabs expand to the next tab stop per CommonMark §2.2), then checks for
651	/// `MD_SETEXT_UNDERLINE_LITERAL` or a dash-only `MD_THEMATIC_BREAK_LITERAL`.
652	///
653	/// Returns `Some(bytes_consumed)` if the line is a setext underline, `None` otherwise.
654	/// The byte count includes only the whitespace tokens consumed during the indent skip,
655	/// NOT the underline token itself. Callers that track byte budgets must subtract this.
656	///
657	/// This is the shared helper for setext detection in inline contexts.
658	/// Used by `has_matching_code_span_closer`, `parse_inline_html`, and `parse_inline_item_list`.
659	///
660	/// Context safety: this function does NOT call `allow_setext_heading` because the token
661	/// stream itself encodes context. In blockquotes, `R_ANGLE` tokens appear after NEWLINE
662	/// before content, so the whitespace-only skip naturally rejects those lines. In list
663	/// items, the indent reflected in the token stream is the raw line indent, and the
664	/// `columns < 4` check correctly rejects lines with 4+ columns of leading whitespace.
665	pub(crate) fn at_setext_underline_after_newline(p: &mut MarkdownParser) -> Option<usize> {
666	    let mut columns = 0;
667	    let mut bytes_consumed = 0;
668	    while columns < INDENT_CODE_BLOCK_SPACES
669	        && p.at(MD_TEXTUAL_LITERAL)
670	        && p.cur_text().chars().all(|c| c == ' ' || c == '\t')
671	    {
672	        for c in p.cur_text().chars() {
673	            match c {
674	                ' ' => columns += 1,
675	                '\t' => columns += TAB_STOP_SPACES - (columns % TAB_STOP_SPACES),
676	                _ => {}
677	            }
678	        }
679	        bytes_consumed += p.cur_text().len();
680	        p.bump(MD_TEXTUAL_LITERAL);
681	    }
682	    if columns >= INDENT_CODE_BLOCK_SPACES {
683	        return None;
684	    }
685	    let is_setext = p.at(MD_SETEXT_UNDERLINE_LITERAL)
686	        || (p.at(MD_THEMATIC_BREAK_LITERAL) && is_dash_only_thematic_break_text(p.cur_text()));
687	    if is_setext {
688	        Some(bytes_consumed)
689	    } else {
690	        None
691	    }
692	}
