694	/// Token-based check: does an inline span of `byte_len` bytes cross a setext underline?
695	///
696	/// Walks tokens via lookahead. At each NEWLINE, delegates to
697	/// [`at_setext_underline_after_newline`] — the same detection used by
698	/// `has_matching_code_span_closer` and `parse_inline_item_list`.
699	pub(crate) fn inline_span_crosses_setext(p: &mut MarkdownParser, byte_len: usize) -> bool {
700	    p.lookahead(|p| {
701	        let mut remaining = byte_len;
702	        loop {
703	            if remaining == 0 || p.at(T![EOF]) {
704	                return false;
705	            }
706	            if p.at(NEWLINE) {
707	                let nl_len = p.cur_text().len();
708	                if nl_len > remaining {
709	                    return false;
710	                }
711	                remaining -= nl_len;
712	                p.bump(NEWLINE);
713	                if let Some(ws_bytes) = at_setext_underline_after_newline(p) {
714	                    // Only flag if the whitespace consumed is still within our span
715	                    return ws_bytes <= remaining;
716	                }
717	                continue;
718	            }
719	            let tok_len = p.cur_text().len();
720	            if tok_len > remaining {
721	                return false;
722	            }
723	            remaining -= tok_len;
724	            p.bump_any();
725	        }
726	    })
727	}
